"""
Interactive Web Visualizer for LangGraph Multi-Agent Forensic Engine.
Renders the agent state graph with Mermaid.js and provides an interactive inspection workbench.
"""

from app.services.langgraph_pipeline import compiled_investigation_graph


def get_langgraph_mermaid() -> str:
    """Returns the raw Mermaid diagram string generated by LangGraph."""
    return compiled_investigation_graph.get_graph().draw_mermaid()


